// La llanta quita una fracción de la velocidad lateral en cada paso.
// Con agarre alto el carro va en rieles; con freno de mano o en tierra, derrapa.
const agarre = suelo.agarre * (ctrl.mano ? p.agarreMano : 1) * (c.resbalon > 0 ? e.resbalonAgarre : 1);
const perdida = vLat * (1 - Math.exp(-agarre * dt));
vLat -= perdida;
// Parte de lo que se come la llanta regresa como empuje: sales disparado del derrape
if (vLong > 0 && !ctrl.mano) vLong = Math.min(vMax, vLong + Math.abs(perdida) * p.recuperacion);

// Al girar NO se rota la velocidad: queda velocidad lateral que el agarre irá matando
c.w += (objetivo - c.w) * (1 - Math.exp(-p.respuestaGiro * dt));
c.angulo = normalizar(c.angulo + c.w * dt);

// Cada control se aplica en cuanto llega, con el mismo paso que usó el navegador:
// el resultado es idéntico a su predicción y el carro no "se devuelve".
// Un balde de créditos (≈1 por tick) evita ir más rápido mandando controles de más.
while (j.creditos >= 1 && j.cola.length) {
  const ctrl = j.cola.shift()!;
  if (mueve) avanzarCarro(j.carro, ctrl, PARAMETROS_FISICA, this.pista, this.dt);
  j.ultimoSeq = ctrl.seq;
  j.creditos -= 1;
}

// Estado del servidor + los controles que todavía no conoce
const nuevo = copiarCarro(servidor)
for (const p of pendientes) avanzarCarro(nuevo, p.ctrl, PARAMETROS_FISICA, pista, tick)

// Lo que se ve no cambia en este cuadro: el error pasa a una corrección que se desvanece
correccion.x += predicho.x - nuevo.x
correccion.y += predicho.y - nuevo.y
predicho = nuevo

// Explota si cae a un barranco o si lleva más de 0.3 s fuera de la imagen
// de la cámara compartida (la misma proyección que dibuja el navegador).
if (enBarranco(pista, carro.x, carro.y)) return { fuera: 0, motivo: "barranco" };
if (ticksCarrera < DURACION.gracia * tickHz) return { fuera: 0, motivo: null };
if (enVista(camara, carro.x, carro.y, altura, PARAMETROS_CAMARA_PARTIDA, MARGEN_VISTA)) return { fuera: 0, motivo: null };
const total = fuera + 1;
return { fuera: total, motivo: total > DURACION.fueraMax * tickHz ? "atras" : null };
